struct Noisy(&'static str);
impl Drop for Noisy {
    fn drop(&mut self) { println!("drop {}", self.0); }
}
fn main() {
    let _a = Noisy("a");
    let _b = Noisy("b");
    let _c = Noisy("c");
} // end of scope

fn take(s: String) { println!("{s}"); } // s dropped here

fn main() {
    let s = String::from("hi");
    take(s);                 // ownership moves into take
    println!("{}", s.len()); // error[E0382]: borrow of moved value: `s`
}

let x = 5;
let y = x;               // i32 is Copy: bits duplicated
println!("{x} {y}");     // fine, prints 5 5

let s1 = String::from("hi");
let s2 = s1.clone();     // explicit deep copy
println!("{s1} {s2}");   // fine, prints hi hi

