fn calc_len(s: &String) -> usize { s.len() }      // reads only
fn change(s: &mut String) { s.push_str(", world"); } // modifies

fn main() {
    let mut s = String::from("hello");
    let n = calc_len(&s);  // borrow, s still owned by main
    change(&mut s);        // mutable borrow
    println!("{s} {n}");   // hello, world 5
}

let mut v = vec![1, 2, 3];
let first = &v[0];
v.push(4);            // error[E0502]: cannot borrow `v` as mutable
                      // because it is also borrowed as immutable
println!("{first}");

fn first_word(s: &str) -> &str {
    for (i, &b) in s.as_bytes().iter().enumerate() {
        if b == b' ' { return &s[..i]; }
    }
    &s[..]
}

fn main() {
    let mut s = String::from("hello world");
    let word = first_word(&s);
    s.clear();            // error[E0502]: cannot borrow `s` as mutable
    println!("{word}");   // ...because `word` still borrows it
}

fn dangle() -> &String {      // error[E0106]: missing lifetime specifier
    let s = String::from("hi");
    &s                          // s is dropped at the end of dangle
}

fn no_dangle() -> String {      // fix: return the owned value (a move)
    String::from("hi")
}

fn longest(x: &str, y: &str) -> &str {   // error[E0106]: missing lifetime specifier
    if x.len() > y.len() { x } else { y }
}

fn longest<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() > y.len() { x } else { y }
}

use std::cell::RefCell;

fn main() {
    let c = RefCell::new(vec![1, 2, 3]);
    let r = c.borrow();          // run-time shared borrow
    c.borrow_mut().push(4);      // compiles, but panics: already borrowed
    println!("{:?}", r);
}
